import{_ as r,a0 as l,w as u,s as p,I as n,x as t,a1 as a,A as o,ao as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const V=JSON.parse('{"title":"Voyager Linux 23.04：具有華麗外觀且無 Snap 的 Ubuntu 體驗 | LCTT x X-CMD","titleTemplate":false,"description":"Voyager Linux 23.04：具有華麗外觀且無 Snap 的 Ubuntu 體驗 | LCTT (202305) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Voyager Linux 23.04：具有華麗外觀且無 Snap 的 Ubuntu 體驗 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Voyager Linux 23.04：具有華麗外觀且無 Snap 的 Ubuntu 體驗 | LCTT (202305) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202305/20230427.0 ⭐️⭐️ Voyager Linux 23.04 Snap-free Ubuntu Experience with A Gorgeous Look","title":"Voyager Linux 23.04：具有華麗外觀且無 Snap 的 Ubuntu 體驗","tag":"202305","desc":""},"relativePath":"202305/20230427.0 ⭐️⭐️ Voyager Linux 23.04 Snap-free Ubuntu Experience with A Gorgeous Look.md","filePath":"[post].md"}'),g={name:"202305/20230427.0 ⭐️⭐️ Voyager Linux 23.04 Snap-free Ubuntu Experience with A Gorgeous Look.md"};function d(x,e,b,y,m,f){const i=l("Link");return u(),p("div",null,[e[24]||(e[24]=n("h1",{id:"voyager-linux-23-04-具有華麗外觀且無-snap-的-ubuntu-體驗",tabindex:"-1"},[t("Voyager Linux 23.04：具有華麗外觀且無 Snap 的 Ubuntu 體驗 "),n("a",{class:"header-anchor",href:"#voyager-linux-23-04-具有華麗外觀且無-snap-的-ubuntu-體驗","aria-label":"Permalink to “Voyager Linux 23.04：具有華麗外觀且無 Snap 的 Ubuntu 體驗”"},"​")],-1)),e[25]||(e[25]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202305/17/113613lyh2qod5jldqeu91.jpg",alt:""})],-1)),e[26]||(e[26]=n("blockquote",null,[n("p",null,"新版本的 Voyager Linux 23.04 已經來到，我率先試駕以瞭解更多信息。")],-1)),n("p",null,[e[1]||(e[1]=t("在我去年年初上次 ",-1)),a(i,{href:"https://www.debugpoint.com/voyager-live-linux-review-2022/"},{default:o(()=>[...e[0]||(e[0]=[t("測評",-1)])]),_:1}),e[2]||(e[2]=t(" 時，它還是一個嶄露頭角的發行版，提供了很棒的 Ubuntu LTS 體驗。從那時起，這個發行版的方向發生了一些變化。因此，我覺得是時候進行另一輪試駕了。",-1))]),e[27]||(e[27]=n("p",null,"順便説一句，Voyager Linux 基於 Ubuntu Linux，針對 GNOME 桌面進行了出色的定製。之前，它只跟隨 Ubuntu 長期支持（LTS）版本發佈，但從去年開始，它也可跟隨短期 Ubuntu 版本發佈。",-1)),n("p",null,[e[4]||(e[4]=t("在 ",-1)),a(i,{href:"https://www.debugpoint.com/ubuntu-23-04-features/"},{default:o(()=>[...e[3]||(e[3]=[t("Ubuntu 23.04 “Lunar Lobster”",-1)])]),_:1}),e[5]||(e[5]=t(" 發佈後，Voyager 團隊宣佈發佈了 Voyager 23.04。",-1))]),e[28]||(e[28]=s('<h3 id="voyager-linux-23-04-測評" tabindex="-1">Voyager Linux 23.04 測評 <a class="header-anchor" href="#voyager-linux-23-04-測評" aria-label="Permalink to “Voyager Linux 23.04 測評”">​</a></h3><p>與 Voyager 22.04 版本相比，此版本的 ISO 大小增加了約 30%。這可能主要是由於 Ubuntu 自己的軟件包庫。安裝很順利，但安裝程序需要至少 24 GB 的存儲空間（硬性要求）。但是，它使用舊的 Uniquity 安裝程序，而不是新的基於 Flutter 的 Ubuntu 安裝程序。</p><h4 id="外觀及使用感受" tabindex="-1">外觀及使用感受 <a class="header-anchor" href="#外觀及使用感受" aria-label="Permalink to “外觀及使用感受”">​</a></h4><p>如果你運行的是早期版本的 Voyager Linux，你首先會注意到新版的外觀精美。GNOME 桌面現在更具個性化，使用了 “Kora” 主題和許多擴展程序。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/04/Voyager-23.04-Desktop-GNOME.jpg" alt="Voyager 23.04 桌面（GNOME）"></p><p>在底部，你可以看到默認的程序塢，並通過 “Blur my shell” 擴展將其變成了透明的。此外，這一版本還預裝了一系列擴展，並通過適當的設置啓用，以便讓 GNOME 桌面更好看。</p><p>值得重點一提的擴展是非常棒的 “Arc Menu”，可以下拉訪問所有系統應用程序和資源。此外，“Dash to Dock”、“Blur my shell” 和 “Battery Indicator” 也是一些很有用的擴展應用。以下是 Voyager Linux 23.04 中預裝的擴展列表：</p><ul><li>Arch menu</li><li>Battery time</li><li>Blur my shell</li><li>Burn my windows</li><li>Caffeine</li><li>Clipboard history</li><li>Compiz alike magic lamp effect</li><li>Compiz windows effect</li><li>Custom hot corners – Extended</li><li>Dash to Dock</li><li>Desktop Cube</li><li>EasyScreenCast</li><li>Gradient Top Bar</li><li>Lock keys</li><li>Replace Activities Label</li><li>Screen Rotate</li><li>SettingsCenter</li><li>Simple net speed</li><li>Space Bar</li><li>Sur Clock</li><li>Use Avatar in Quick Settings</li></ul><p>所有這些都使桌面在美觀的同時超級高效。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/04/Arc-Menu-with-workspace-view.jpg" alt="帶工作區示圖的 Arc Menu"></p><h4 id="應用、snap-和-flatpak" tabindex="-1">應用、Snap 和 Flatpak <a class="header-anchor" href="#應用、snap-和-flatpak" aria-label="Permalink to “應用、Snap 和 Flatpak”">​</a></h4><p>儘管 Voyager Linux 是基於 Ubuntu 的，但默認情況下完全不包含 Snap。此外，Voyager Linux 23.04 也沒有支持 Ubuntu 從該版本開始刪除 Flatpak 的決定。因此，總而言之，Voyager Linux 23.04 中默認支持的是 Flatpak，而沒有任何 Snap 的痕跡。不僅如此，Firefox 網絡瀏覽器是由原生 deb 模組打包的，而不是 Snap 版本。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/04/Voyager-Linux-23.04-comes-with-default-Flatpak.jpg" alt="Voyager Linux 23.04 自帶默認 Flatpak"></p><p>應用程序列表很龐大且健全。主要應用程序包括 Gedit 文本編輯器、“文件”應用、Firefox 網絡瀏覽器、GIMP 和 LibreOffice 套件。還包括 Thunderbird 電子郵件客户端、Remmina 遠程連接應用程序、Transmission Torrent 客户端和 Pidgin 通訊軟件。</p><p>Voyager 包括 Pitivi、MPV 和 Rhythmbox，均可用於播放視頻和音樂。對於工作和文檔處理，它提供了地圖、日曆、Foliate 閲讀器應用程序、KeePassXC 和 Scrcpy 安卓屏幕鏡像工具。</p><p>由於主 ISO 文件包括了 Xfce 和 GNOME 桌面，因此你也可以體驗一些原生 Xfce 應用程序。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/04/Voyager-Linux-Xfce-Edition-2304.jpg" alt="Voyager Linux Xfce 版本（23.04）"></p><h4 id="box-voyager" tabindex="-1">Box Voyager <a class="header-anchor" href="#box-voyager" aria-label="Permalink to “Box Voyager”">​</a></h4><p>Voyager Linux 帶有自己的很棒的小應用，稱為 “Box Voyager”，它讓你可以一鍵訪問所有桌面自定義設置。它有一個配置項列表，你可以直接使用此應用程序啓動相應的設置。</p><p>此外，要進行更多自定義設置，你可以使用 Voyager Linux 中預裝的多個 Conky 主題。 無需面對安裝和配置 Conky 的麻煩。（LCTT 譯註：Conky 是一個應用於桌面環境的系統監視軟件，可以在桌面上監控系統運行狀態、網絡狀態等一系列參數，而且可自由定製。）</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/04/Box-Voyager-and-Conky-Control.jpg" alt="Box Voyager 和 Conky Control"></p><h4 id="性能表現" tabindex="-1">性能表現 <a class="header-anchor" href="#性能表現" aria-label="Permalink to “性能表現”">​</a></h4><p>安裝了所有定製和擴展後，其性能表現令人印象深刻。它在閒置時佔用 1.3 GB 的內存，CPU 使用率為 1%。但是，隨着你安裝和打開更多應用程序，性能指標可能會上升。</p><p>然而，由於預裝了許多應用程序和 Xfce 桌面，它的安裝需要大約 14 GB 的磁盤空間。另外，正如我之前提到的，整個安裝需要 24 GB 的可用磁盤空間。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/04/Voyager-Linux-Performance.jpg" alt="Voyager Linux 性能"></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>在測評了 Voyager Linux 23.04 之後，我相信它是一個理想的、可以日常使用的非 Snap Ubuntu 變體。如果你不喜歡 Ubuntu GNOME 的默認外觀，並且正在尋找具有穩定的 Ubuntu 長期支持/短期基礎，且設計吸引人的預配置發行版，那麼 Voyager Linux 可能是你的完美選擇。</p><p>此外，最棒的是在同樣的 Ubuntu 基礎上還有一個 Xfce 桌面可以選擇。試一試吧。</p>',28)),n("p",null,[e[7]||(e[7]=t("你可以在其 ",-1)),a(i,{href:"https://voyagerlive.org/"},{default:o(()=>[...e[6]||(e[6]=[t("官方網站",-1)])]),_:1}),e[8]||(e[8]=t(" 下載 Voyager Linux。",-1))]),e[29]||(e[29]=n("p",null,[n("em",null,"（題圖：MJ/2deebcdf-7e04-43bc-beaf-7059e80b8057）")],-1)),e[30]||(e[30]=n("hr",null,null,-1)),n("p",null,[e[10]||(e[10]=t("via: ",-1)),a(i,{href:"https://www.debugpoint.com/voyager-linux-review-23-04/"},{default:o(()=>[...e[9]||(e[9]=[t("https://www.debugpoint.com/voyager-linux-review-23-04/",-1)])]),_:1})]),n("p",null,[e[15]||(e[15]=t("作者：",-1)),a(i,{href:"https://www.debugpoint.com/author/admin1/"},{default:o(()=>[...e[11]||(e[11]=[t("Arindam",-1)])]),_:1}),e[16]||(e[16]=t(" 選題：",-1)),a(i,{href:"https://github.com/lkxed/"},{default:o(()=>[...e[12]||(e[12]=[t("lkxed",-1)])]),_:1}),e[17]||(e[17]=t(" 譯者：",-1)),a(i,{href:"https://github.com/XiaotingHuang22"},{default:o(()=>[...e[13]||(e[13]=[t("XiaotingHuang22",-1)])]),_:1}),e[18]||(e[18]=t(" 校對：",-1)),a(i,{href:"https://github.com/wxy"},{default:o(()=>[...e[14]||(e[14]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[21]||(e[21]=t("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[19]||(e[19]=[t("LCTT",-1)])]),_:1}),e[22]||(e[22]=t(" 原創編譯，",-1)),a(i,{href:"https://linux.cn/"},{default:o(()=>[...e[20]||(e[20]=[t("Linux中國",-1)])]),_:1}),e[23]||(e[23]=t(" 榮譽推出",-1))])])}const k=r(g,[["render",d]]);export{V as __pageData,k as default};
